1	{ config, lib, pkgs, ... }:
2	
3	let
4	  # Seeded configuration, copied verbatim from the reference node.
5	  promFile = name: ./files/prometheus + "/${name}";
6	
7	  promEtc = lib.listToAttrs (map
8	    (name: lib.nameValuePair "prometheus/${name}" { source = promFile name; })
9	    [
10	      "prometheus.yml"
11	      "blackbox.yml"
12	      "rules/rules_recording.yml"
13	      "rules/alerts_default.yml"
14	      "rules/alerts-staged.yml"
15	      "rules/rules_old.yml.disabled"
16	      "targets/node_main.yml"
17	      "targets/node_decom.yml"
18	      "targets/probe_http_main.yml"
19	      "targets/probe_auth_main.yml"
20	      "targets/probe_tcp_main.yml"
21	    ]);
22	
23	  alertSink = pkgs.writeScriptBin "alert-sink"
24	    ("#!${pkgs.python3}/bin/python3\n" + builtins.readFile ./files/alert-sink.py);
25	
26	  inventory = pkgs.writeTextFile {
27	    name = "node31-inventory";
28	    executable = true;
29	    destination = "/bin/node31-inventory";
30	    text = ''
31	      #!${pkgs.runtimeShell}
32	      export PATH=${lib.makeBinPath [ pkgs.gawk pkgs.coreutils ]}
33	    '' + builtins.readFile ./files/node31-inventory.sh;
34	  };
35	
36	  nginxConf = pkgs.writeText "nginx.conf" ''
37	    user www-data;
38	    worker_processes auto;
39	    pid /run/nginx.pid;
40	
41	    events {
42	    	worker_connections 768;
43	    }
44	
45	    http {
46	    	sendfile on;
47	    	tcp_nopush on;
48	    	types_hash_max_size 2048;
49	
50	    	include ${pkgs.nginx}/conf/mime.types;
51	    	default_type application/octet-stream;
52	
53	    	ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;
54	    	ssl_prefer_server_ciphers on;
55	
56	    	access_log /var/log/nginx/access.log;
57	    	error_log /var/log/nginx/error.log;
58	
59	    	gzip on;
60	
61	    	include /etc/nginx/conf.d/*.conf;
62	    }
63	  '';
64	
65	  nginxBin = "${pkgs.nginx}/bin/nginx -c /etc/nginx/nginx.conf";
66	
67	  # Operator-facing nginx command: default to the node config like the reference does.
68	  nginxCli = pkgs.writeShellScriptBin "nginx" ''
69	    exec ${pkgs.nginx}/bin/nginx -c /etc/nginx/nginx.conf "$@"
70	  '';
71	
72	  # Compatibility names for the binaries that the reference node exposes.
73	  compatBins = pkgs.runCommand "prometheus-compat-bins" { } ''
74	    mkdir -p $out/bin
75	    ln -s ${pkgs.prometheus-alertmanager}/bin/alertmanager $out/bin/prometheus-alertmanager
76	    ln -s ${pkgs.prometheus-blackbox-exporter}/bin/blackbox_exporter $out/bin/prometheus-blackbox-exporter
77	    ln -s ${pkgs.prometheus-node-exporter}/bin/node_exporter $out/bin/prometheus-node-exporter
78	  '';
79	
80	  hardenedPrometheus = {
81	    AmbientCapabilities = "";
82	    CapabilityBoundingSet = "";
83	    DeviceAllow = "/dev/null rw";
84	    DevicePolicy = "strict";
85	    LimitMEMLOCK = 0;
86	    LimitNOFILE = 8192;
87	    LockPersonality = true;
88	    MemoryDenyWriteExecute = true;
89	    NoNewPrivileges = true;
90	    PrivateDevices = true;
91	    PrivateTmp = true;
92	    PrivateUsers = true;
93	    ProtectControlGroups = true;
94	    ProtectHome = true;
95	    ProtectKernelModules = true;
96	    ProtectKernelTunables = true;
97	    ProtectSystem = "full";
98	    RemoveIPC = true;
99	    RestrictNamespaces = true;
100	    RestrictRealtime = true;
101	    SystemCallArchitectures = "native";
102	  };
103	in
104	{
105	  networking.hostName = "node31";
106	  networking.hosts."127.0.0.1" = [ "node31.n31.test" ];
107	  networking.firewall.enable = false;
108	  time.timeZone = "Etc/UTC";
109	  i18n.defaultLocale = "C.UTF-8";
